mapper.update:
UPDATE lambda_event_receipts
SET status = 'ADMITTED', run_id = #{runId}
WHERE event_id = #{eventId} AND lambda_assignment_id = #{lambdaAssignmentId} AND status = 'PENDING'

UPDATE lambda_event_receipts
SET status = 'COMPLETED', completed_at = CURRENT_TIMESTAMP(3)
WHERE event_id = #{eventId} AND lambda_assignment_id = #{lambdaAssignmentId}

mapper.select:
SELECT event_id
FROM lambda_event_receipts
WHERE lambda_assignment_id = 0 AND completed_at < #{cutoff}
ORDER BY completed_at
LIMIT #{limit}

